import React from 'react';
import { AlertTriangle } from 'lucide-react';

interface DisclaimerBannerProps {
  compact?: boolean;
}

const DISCLAIMER =
  'AXONOVA is an educational image-classification prototype. Its output is not a medical diagnosis and must not be used to make healthcare decisions. Medical scans should be interpreted by qualified healthcare professionals.';

const DisclaimerBanner: React.FC<DisclaimerBannerProps> = ({ compact = false }) => {
  if (compact) {
    return (
      <div
        role="alert"
        className="flex items-start gap-2.5 p-3 rounded-xl bg-amber-500/10 border border-amber-500/25 text-amber-200"
      >
        <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" aria-hidden="true" />
        <p className="text-xs leading-relaxed min-w-0">{DISCLAIMER}</p>
      </div>
    );
  }

  return (
    <div
      role="alert"
      className="p-4 rounded-xl bg-slate-900/90 border border-amber-500/30 shadow-lg shadow-amber-950/10"
    >
      <div className="flex items-start gap-3">
        <div className="p-2 rounded-lg bg-amber-500/10 border border-amber-500/20 shrink-0">
          <AlertTriangle className="w-5 h-5 text-amber-400" aria-hidden="true" />
        </div>
        <div className="space-y-1 min-w-0">
          <h4 className="text-sm font-semibold text-amber-300">
            Important Medical Safety Notice
          </h4>
          <p className="text-xs text-slate-300 leading-relaxed">{DISCLAIMER}</p>
        </div>
      </div>
    </div>
  );
};

export default DisclaimerBanner;
